@CrossOrigin
@RestController
@RequestMapping("/InterviewQuery")
public class InterviewQueryRestController extends BaseSpringRestController {
	
	public InterviewQueryRestController( InterviewService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Interview using a UUID
     * @param		UUID interviewId
     * @return		Interview
     */    
    @GetMapping("/load")
    public Interview load( @RequestParam(required=true) UUID interviewId ) {
    	Interview entity = null;

    	try {  
    		entity = service.getInterview( new InterviewFetchOneSummary( interviewId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Interview using Id " + interviewId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Interview business objects
     * @return		Set<Interview>
     */
    @GetMapping("/")
    public List<Interview> loadAll() {                
    	List<Interview> interviewList = null;
        
    	try {
            // load the Interview
            interviewList = service.getAllInterview();
            
            if ( interviewList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Interviews" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Interviews ", exc );
        	return null;
        }

        return interviewList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Interview interview = null;
    protected InterviewService service = null;
    private static final Logger LOGGER = Logger.getLogger(InterviewQueryRestController.class.getName());
    
}
